TURN = r"\[(\d\d:\d\d)\] (\w+): (.*)"
def chunk(text, asker="Customer", n=300):
    groups, out = [], []
    for ln in text.splitlines():
        if re.match(TURN, ln)[2] == asker or not groups:
            groups.append([])
        groups[-1].append(ln)
    for g in groups:
        if len("\n".join(g)) <= n:
            out.append("\n".join(g)); continue
        for ln in g[1:]:  # {{question on each piece}}
            m = re.match(TURN, ln)
            head, p = f"{g[0]}\n[{m[1]}] {m[2]}: ", ""
            for s in re.split(r"(?<=[.?!]) ", m[3]):
                if p and len(head + p + s) > n:
                    out.append(head + p.strip()); p = ""
                p += s + " "
            out.append(head + p.strip())
    return out

def meta(c):
    ts = re.findall(
        r"^\[(\d\d:\d\d)\] (\w+):", c, re.M)
    return {"start": ts[0][0],
            "speakers": sorted({w for _, w in ts})}

